@Component("identityDocument-handler")
@ProcessingGroup("identityDocument-processing-group")
public class IdentityDocumentEventHandler {
	
	// core constructor
	IdentityDocumentEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateIdentityDocumentEvent
     */
    @EventHandler
    public void handle( CreateIdentityDocumentEvent event) {
        entityManager.persist(new IdentityDocument(event.getIdentityDocumentId(), event.getDocumentNumber(), event.getIssuingCountry(), event.getExpirationDate(), event.getKycProfile(), event.getDocumentType()));
    }

    /*
     * @param	event UpdateIdentityDocumentEvent
     */
    @EventHandler
    public IdentityDocument handle( UpdateIdentityDocumentEvent event) {
    	entityManager.merge(new IdentityDocument(event.getIdentityDocumentId(), event.getDocumentNumber(), event.getIssuingCountry(), event.getExpirationDate(), event.getKycProfile(), event.getDocumentType()));
    }
    
    /*
     * @param	event DeleteIdentityDocumentEvent
     */
    @EventHandler
    public void on( DeleteIdentityDocumentEvent event) {
    	IdentityDocument entity = new IdentityDocument();
   
    	// ------------------------------------------
    	// apply the IdentityDocumentId
    	// ------------------------------------------
    	entity.setIdentityDocumentId( event.getIdentityDocumentId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final IdentityDocumentRepository identityDocumentEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(IdentityDocumentEventHandler.class.getName());

}
